def get_state_data(self, state):
    """Return the active data for a state, or None if it is inactive."""
    state_id = state if isinstance(state, str) else state.id
    return self._state_data.get(state_id)

@property
def state_data_values(self):
    return deepcopy(self._state_data)

def set_state_data(self, state, key, value):
    state_id = state if isinstance(state, str) else state.id
    data = self._state_data.get(state_id)
    declaration = next((s for s in self.states_map.values() if s.id == state_id), None)
    if data is None or declaration is None or key not in declaration.data:
        raise InvalidDefinition(f"State data key {state_id}.{key} is not active or declared")
    variable = declaration.data[key]
    if isinstance(variable, DataVar):
        variable.validate(value)
    old = data[key]
    data[key] = value
    self._data_changes.append(DataChangeInfo(state_id, key, old, value))

def get_data_changes(self):
    return list(self._data_changes)

def _enter_state_data(self, state, restored=None):
    if restored is not None:
        self._state_data[state.id] = deepcopy(restored)
        return
    self._state_data[state.id] = {
        key: (value.initial_value() if isinstance(value, DataVar) else
              value() if callable(value) else deepcopy(value))
        for key, value in state.data.items()
    }

def _scoped_state_data(self, state):
    result = {}
    for item in reversed([state, *state.ancestors()]):
        result.update(self._state_data.get(item.id, {}))
    return result

