def _initialize_state_data(self, target, transitions):
    restored = None
    for transition in transitions:
        for destination in transition.targets:
            if destination.is_history:
                snapshot = self.sm._history_data.get(destination.id, {})
                if target.id in snapshot:
                    restored = snapshot[target.id]
    self.sm._enter_state_data(target, restored)

